"""Japanese explanations for the authored course; note data is shared, not duplicated."""

COURSES = {
    "find_c": ("01 中央の C：ト音譜表の出発点", "二つ並ぶ黒鍵の左が C です。中央の C は C4（MIDI 60）です。\nト音譜表の一番下の線は E4。C4 はその下の加線に書きます。\nC4、D4、E4、C4 を弾きます。白い音符で符幹がない全音符は 4 拍です。\n時間制限はありません。音が合ったら鍵盤を離すと次へ進みます。"),
    "right_five": ("02 右手の 5 本指：C D E F G", "右手の親指を C4、人差し指 D4、中指 E4、薬指 F4、小指 G4 に置きます。\n隣の鍵盤へ動くと、楽譜でも線と間を交互に進みます。黒い音符と符幹の四分音符は 1 拍です。\n4/4 は四分音符を 1 拍として 1 小節に 4 拍あることを示します。ゆっくり数えて構いません。"),
    "left_bass": ("03 左手の読譜：低音域の C と A", "下はヘ音譜表です。一番下の線は G2、一番上は A3 です。まず C3 と A2 を探しましょう。\n左手だけを弾き、右手の譜表には休符を表示します。白い音符と符幹の二分音符は 2 拍です。\nC3、G3、A2、E3 を 2 回弾きます。C3 を C4 で代用せず、楽譜のオクターブに合わせてください。"),
    "c_chord": ("04 最初のコード：C E G", "C の長三和音は C・E・G です。右手で C4・E4・G4 を弾きます。1・3・5 指は一例です。\n縦にそろった音は一緒に響かせます。一音ずつゆっくり足しても、そろうまで待機します。\n余分な音は赤く表示します。正解したら三つの鍵盤を離して次へ進んでください。"),
    "am_chord": ("05 短三和音：A C E", "Am は A・C・E です。右手で A3・C4・E4 を弾きます。A3 は中央の C より低い音です。\n低い音はト音譜表の下に加線が増えます。鍵盤ラベルと音名を見ながら少しずつ覚えましょう。\nC と Am の響きを聴き比べ、楽譜に合わせてゆっくり練習してください。"),
    "two_hands": ("06 両手の協調：C と Am の 4 小節", "オリジナルの C・Am・C・Am の 4 小節です。右手はコード、左手は C3 または A2 のベース音です。\n上下の譜表で縦にそろった音は同じタイミングの音です。\n先に左手、次に右手を足しても構いません。そろったら自分で 4 拍数え、離して次へ進みます。"),
    "white_key_walk": ("07 オリジナル『白鍵の小道』：4 小節を読む", "C 長調の白鍵だけを使う右手の小曲です。まず第 1 小節、次に小節をつないで弾きます。\n楽譜で上がる音は鍵盤でも通常は右へ、下がる音は左へ動きます。同じ音の反復も一度離して押し直します。\n慣れたら音名を隠して試せます。いつでも再表示でき、速度や再テストの条件はありません。"),
    "left_five": ("08 左手の 5 本指：C3 から上へ", "左手の小指を C3、薬指 D3、中指 E3、人差し指 F3、親指 G3 に置きます。\nヘ音譜表の C3 と G3 を目印にし、間の音を探します。右手の C4 と混同しないでください。\n上行は小指から親指、下行は逆です。手首を自然に保ち、速さを求めず練習しましょう。"),
    "read_thirds": ("09 線から線、間から間：2 度と 3 度", "C→D は隣の 2 度で、線から間へ移ります。C→E は 3 度で位置を一つ飛ばします。\n隣接音の後に C E G を弾き、音符の距離を見比べてください。\n同音は離してから押し直します。音名表示は自由にオン・オフできます。"),
    "long_short": ("10 1 拍・2 拍・4 拍：音の長さ", "四分音符は 1 拍、二分音符は 2 拍、全音符は 4 拍です。まず試聴し、自分で拍を数えます。\n長い音は何度も打鍵するという意味ではありません。同音の音符が繰り返し書かれたときに押し直します。\nこのモードは音高のみを判定します。保持時間やリズムは自分で数えながら練習してください。"),
    "eighth_dotted": ("11 半拍と付点：八分音符", "旗が一つある八分音符は半拍です。付点四分音符は 1 拍半です。\n第 1 小節は八つの音で 4 拍。第 2 小節では長短の組み合わせに注意します。\nまず聴き、ゆっくり鍵盤を探してください。アプリはリズムを採点しないため、聴くことと数えることで練習します。"),
    "f_chord": ("12 F の長三和音：F A C", "F は F・A・C です。右手で F3 A3 C4 を弾きます。1・3・5 指は一例です。\n前半は右手のみ、後半は左手の F2 を加えます。左右の F はオクターブが違います。\n届かない場合は片手ずつ練習し、手を無理に広げないでください。"),
    "g_chord": ("13 G の長三和音：G B D", "G は G・B・D です。右手で G3 B3 D4 を弾きます。B3 は C4 の左隣の白鍵です。\n三つの音が楽譜で 3 度ずつ積み重なる形を確認しましょう。\n後半は左手の G2 を加えます。白鍵一つ飛ばしが常に長三和音になるわけではなく、音程で種類を決めます。"),
    "dm_chord": ("14 Dm の短三和音：D F A", "Dm は D・F・A。右手は D4 F4 A4 です。D→F は短 3 度、F→A は長 3 度です。\nC や Am と聴き比べましょう。印象の言葉だけでコードを定義しないことも大切です。\n各音を確認してから重ね、後半は左手の D3 を足します。"),
    "em_chord": ("15 Em の短三和音：E G B", "Em は E・G・B。右手は E4 G4 B4 です。B4 は C5 の左隣です。\nE→G は短 3 度、G→B は長 3 度です。白鍵だけでも短三和音を作れます。\n後半は左手の E3 を加え、上下の譜表の高さを確認します。"),
    "primary_cadence": ("16 C F G C：最初のコード進行", "C 長調の C・F・G は I・IV・V です。C に戻るときの落ち着きを聴きましょう。\n4 小節を 2 回繰り返します。次の根音を先に見てから右手を動かします。\nコードを変える前に鍵盤を離します。一度にそろわなくても、ゆっくり音を足せます。"),
    "c_first_inversion": ("17 C の第 1 転回形：E G C", "C E G の一番低い C を 1 オクターブ上げると E G C。構成音は同じ C のコードです。\nC4 E4 G4 と E4 G4 C5 を交互に弾き、最低音の変化を聴きます。\n楽譜練習は指定のオクターブが必要です。自由なコード練習では「転回形自由」を選べます。"),
    "c_second_inversion": ("18 C の第 2 転回形：G C E", "第 2 転回形は G が最低音です。ここでは G3 C4 E4 を使います。\n基本形 C4 E4 G4、第 1 転回形 E4 G4 C5、第 2 転回形 G3 C4 E4 を比較します。\n根音と現在の最低音を分けて考えてください。構成音はすべて C・E・G です。"),
    "common_tones": ("19 C と Am：小さな移動でつなぐ", "C は C E G、Am は A C E です。C と E が共通します。Am を C4 E4 A4 の配置にします。\nC4 E4 G4 から一つの音だけ動かすため、手の位置が近くなります。\nこの入門モードではグループごとに離して弾き直します。レガートや共通音の保持を判定する課題ではありません。"),
    "broken_c": ("20 分散和音：C E G を順に弾く", "同時に弾くと和音、順に弾くと分散和音です。右手で C4 E4 G4 を確認します。\n各音 1 拍で C E G E、後半は C5 へ上がり、中央の C に戻ります。\nC5 には手を移動して届かせ、無理に指を広げないでください。"),
    "broken_am": ("21 分散和音：Am と C の対話", "A3 C4 E4 を順に弾き、次に C4 E4 G4 へ移ります。二つのコードの共通音を確認します。\n2 小節を一つのフレーズとして、上行と下行を聴き比べます。\n運指は参考です。アプリは音高とオクターブを確認し、どの指を使ったかは判定しません。"),
    "left_broken": ("22 左手伴奏：根音と第 5 音", "左手で C3→G3、A2→E3、F2→C3、G2→D3 を弾きます。各コードの根音と第 5 音です。\n各音 2 拍。音域が変わるときは前腕も動かし、手首だけをひねらないようにしましょう。\n左手だけで和声の向きを聴き、慣れたら両手の練習曲へ進めます。"),
    "dominant_seventh": ("23 G7 から C：解決を聴く", "G7 は G B D F。G に F が加わります。右手 B3 D4 F4、左手 G2 で弾きます。\nC へ進む際、B3→C4、F4→E4 の半音の動きを聴きましょう。\n右手では G を省いていますが、両手全体には G7 の四つの構成音がそろっています。"),
    "soft_sevenths": ("24 Cmaj7 と Am7：七の和音", "Cmaj7 は C E G B、Am7 は A C E G。三和音の上にさらに 3 度を重ねます。\n右手は E4 G4 B4 と C4 E4 G4、左手は C3 と A2。片手の広がりを抑えます。\n2 回聴き比べたら練習曲を選びましょう。速度や再テストは進級条件ではありません。"),
    "song_twinkle": ("S01 きらきら星・片手の旋律", "伝統旋律『Ah! vous dirai-je, maman』の C 長調入門編曲です。歌詞なしの 12 小節です。\n4 小節ずつ覚え、中央の繰り返しと最後の再現を聴きましょう。G→A の手の位置に注意します。\n四分音符は 1 拍、二分音符は 2 拍です。段送りボタンで先を確認できます。"),
    "song_mary": ("S02 メリーさんのひつじ・5 本指の旋律", "伝統的な童謡旋律の C 長調入門編曲です。歌詞はなく、C4～G4 の音を使います。\n同じ E や D が続くときも、一度離して弾き直します。二分音符は 2 回打鍵する意味ではありません。\n前半と後半の終わり方を聴き比べ、まず音を確かめましょう。"),
    "song_frere": ("S03 フレール・ジャック・八分音符", "フランスの伝統的な輪唱旋律の C 長調編曲です。この譜面では一つの旋律だけを弾きます。\n第 5・6 小節の G A G F は八分音符四つで 2 拍、その後の E と C は各 1 拍です。\n終わりの C4 G3 C4 では右手を左に移します。オクターブを確認してください。"),
    "song_ode": ("S04 歓喜の歌・主題（交響曲全曲ではありません）", "ベートーヴェン交響曲第 9 番の主題による、C 長調・片手の入門編曲です。16 小節の主題のみです。\n同音は弾き直します。第 4 小節の E は付点四分音符で 1 拍半、次の D は半拍です。\n第 9 小節から対照的なフレーズです。4 小節ずつ確認してからつなげましょう。"),
    "song_morning": ("S05 オリジナル『朝の光』・5 本指", "C4 D4 E4 F4 G4 を使う、右手 8 小節のオリジナル教材です。隣接音と 3 度を練習します。\n4 小節ごとに一つのフレーズです。第 2 フレーズは似た形で、結びが変わります。\n手を自然に保ち、正しい音を弾いて離すことから始めましょう。"),
    "song_steps": ("S06 オリジナル『階段』・上行と下行", "C5 まで上がり、白鍵を下がる右手 8 小節の教材です。\n5 本指の固定位置ではありません。無理に広げず、手の位置を移してください。\n線と間を順に上がる動きと G4→C5 の跳躍を見比べます。"),
    "song_echo": ("S07 オリジナル『こだま』・両手の応答", "右手の問いに左手が 1 オクターブ下で答える、8 小節の教材です。同時には弾きません。\n休符がある側は力を抜き、今のフレーズが上・下どちらの譜表かを確認します。\n両手で似た形を交互に弾き、ト音・ヘ音譜表を結び付けましょう。"),
    "song_am_river": ("S08 オリジナル『短調の川』・A 短調", "A C E と D F A を中心にした 8 小節です。すべて白鍵ですが、中心音は A です。\n右手は A3 から始まります。中央の C より低い加線と、A4 への手の移動を確認します。\n最後の A3 が C 長調の教材と違う落ち着きを持つか、聴いてみましょう。"),
    "song_bass_path": ("S09 オリジナル『低音の散歩』・左手の旋律", "ヘ音譜表を読む、左手 8 小節の教材です。右手は休みます。\nC4 はヘ音譜表の上の加線にあり、第 1 課の中央の C と同じ鍵盤です。\n後半はさらに低い音域に移ります。音名だけでなくオクターブも確認してください。"),
    "song_four_homes": ("S10 オリジナル『四つの窓』・両手の和音", "両手 8 小節。C・Am・F・G、次に C・Dm・G7・C と進みます。\n右手は近い転回形、左手は根音です。まず両譜表を別々に読み、グループごとに音をそろえます。\n各小節を 4 拍数えてから離してみましょう。保持時間は採点しません。"),
    "song_lantern": ("S11 オリジナル『灯り』・2 拍ごとの両手和音", "1 小節に二つの両手和音がある、8 小節の教材です。左手は低音、右手は二音・三音の簡略な配置です。\n左手の C3→G3 などの 5 度移動を見てから右手を読みます。音はゆっくり足せます。\n独立した旋律と長い低音ではなく、両手で和音を弾く練習です。各グループの正解後は全鍵盤を離してください。"),
    "song_evening": ("S12 オリジナル『夕風』・七の和音", "Cmaj7・Am7・Dm7・G7 の近い配置を練習する両手 12 小節の教材です。\n四つの構成音を両手に分け、右手だけで 7 度を広げる必要がないようにします。\n第 24 課の後におすすめです。ヒントと修正を使いながら練習できます。"),
}

# Same order and answer indices as tutorial._ACTIVITIES; only displayed text changes.
QUIZZES = (
    ("初めて C のコードを学ぶとき、役に立つ方法は？", ("画面の手の形だけを覚える", "C E G と言ってから鍵盤を探し、弾いて聴く", "すぐに高度なコードをすべて練習する"), "記号・音名・鍵盤・響きを結び付けましょう。既読は技能の習得を意味しません。"),
    ("E の半音上はどの音ですか？", ("F", "F#", "G"), "E と F の間に黒鍵はなく、半音です。B と C も同じです。"),
    ("F 長調の第 4 音はどう書きますか？", ("A#", "Bb", "B"), "F G A Bb C D E は各文字を一度ずつ使います。A# と Bb は同じ鍵盤ですが、ここでは Bb と書きます。"),
    ("F# の長 3 度上の正しい音名は？", ("A", "A#", "Bb"), "文字は F G A と数えるので A 系の音です。半音四つにするため A# になります。"),
    ("C–D# と C–Eb は同じ鍵盤なので、音程名も同じですか？", ("同じ。どちらも短 3 度", "異なる。増 2 度と短 3 度"), "音程名は文字の隔たりと半音数の両方で決まります。鍵盤の距離だけでは決まりません。"),
    ("C の長三和音を短三和音にするには、どの音を変えますか？", ("C を B にする", "E を Eb にする", "G を Gb にする"), "C E G → C Eb G。第 3 音を半音下げ、根音と第 5 音は保ちます。"),
    ("D の長三和音の構成音は？", ("D F A", "D F# A", "D G A"), "D の長 3 度上が F#、完全 5 度上が A です。白鍵一つ飛ばしが常に正しいわけではありません。"),
    ("左手 C3、右手 E4 G4 C5。全体はどの形ですか？", ("基本形", "第 1 転回形", "第 2 転回形"), "両手全体の最低音を見ます。C が最低音なので基本形です。"),
    ("C/D は必ず C 三和音の転回形ですか？", ("はい。スラッシュコードはすべて転回形", "いいえ。D は C 三和音の構成音ではない"), "スラッシュはベース音を指定します。ベース音がコード構成音である場合に、その位置による転回形を考えます。"),
    ("Cmaj7 と C7 はどこが違いますか？", ("第 3 音 E / Eb", "第 7 音 B / Bb", "根音 C / B"), "どちらも C E G が基本です。maj7 は B、7 は Bb を加えます。"),
    ("Cm7 の第 5 音を半音下げると？", ("Cm7b5", "Cdim7", "Cmaj7"), "C Eb G Bb → C Eb Gb Bb。Cdim7 はさらに Bb を Bbb に下げます。"),
    ("F 長調の iii7 は何ですか？", ("Am7", "A7", "Abmaj7"), "F G A Bb C D E の第 3 音 A から一つおきに取り、A C E G になります。"),
    ("C 長調で G7 が属機能を持つとき、典型的な解決先は？", ("主和音 C に戻る", "必ず Am に進む", "C には戻れない"), "B→C、F→E の動きで、よくある V7–I の解決を作ります。実際の音楽は別の進み方もできます。"),
    ("A 短調で Em を E7 にするとき、重要な上方変化は？", ("G → G#", "B → C", "E → F"), "G# は A の半音下の導音です。E7 には第 7 音 D も加わります。自然短音階の G 自体が間違いなのではありません。"),
    ("C–A7–Dm–G7 の A7 の一般的な解釈は？", ("C 長調のダイアトニックな vi", "Dm のセカンダリー・ドミナント V7/ii", "必ず A 長調に転調している"), "A7 の C# は調外音で、Dm に向かいやすくなります。一つの調外コードだけで全曲の転調は断定できません。"),
    ("Cadd9 と C9 の重要な違いは？", ("C9 には短 7 度の Bb もある", "Cadd9 に第 3 音 E はない", "二つは完全に同じ"), "add9 は三和音に第 9 音を追加します。C9 は属七型の構造に第 9 音を加えます。"),
    ("C13 は七種類の音を必ず同時に弾きますか？", ("必ず。欠けたら C13 ではない", "必ずしもそうではなく、配置では一部を省略できる"), "理論上の構成音と実際の配置は区別します。E・Bb・A などを重視し、低音や他の楽器との分担で残りを考えます。"),
    ("配置の総移動量が小さいほど、必ず良い音楽になりますか？", ("はい。それだけが基準", "いいえ。旋律・リズム・表現の目的にもよる"), "移動量は配置の比較に役立つ客観的な量ですが、美的な判断を代わりに行うものではありません。"),
    ("同じ問題で続けて間違えたとき、有効な次の行動は？", ("とにかく速く弾く", "根音・第 3 音・第 5 音を言い、違いを確認してゆっくり弾く", "さらに高度な問題へ飛ぶ"), "鍵盤探し・構成・ベース音のどこで間違えたかを確かめ、正確にできてから速度を上げましょう。"),
)
